import TodaysWeather from "./components/TodaysWeather/TodaysWeather";
import WeeklyWeather from "./components/WeeklyWeather/WeeklyWeather";

import "./App.css";
import { useState } from "react";

function App() {
  const [input, setInput] = useState();
  return (
    <div>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          setInput(e.target[0])
        }}
      >
        <input type="text" />
        <input type="submit" />
      </form>
      <TodaysWeather />
      <WeeklyWeather />
    </div>
  );
}

export default App;
